import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type CheckboxPart = "root" | "label" | "control" | "indicator" | "hiddenInput";

export const anatomy: Anatomy<CheckboxPart> = createAnatomy("checkbox").parts(
  "root",
  "label",
  "control",
  "indicator",
  "hiddenInput",
);

export const parts: Record<CheckboxPart, AnatomyPart> = anatomy.build();

/**
 * The root is the `<label>`, and the hidden input is inside it. That is what
 * makes a click anywhere on the row toggle the box without a single handler on
 * the root — and why there must not be one: the browser already forwards the
 * click to the input, and a second handler would toggle it back.
 */

import { visuallyHiddenStyle } from "../../a11y/visually-hidden";
import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./checkbox.anatomy";
import { getHiddenInputId, getLabelId, getRootId } from "./checkbox.dom";
import type { CheckboxApi, CheckboxSchema } from "./checkbox.types";

export function connect<T extends PropTypes>(
  service: Service<CheckboxSchema>,
  normalize: NormalizeProps<T>,
): CheckboxApi<T> {
  const { context, prop, computed, state, send, scope } = service;

  const checked = context.get("checked");
  const indeterminate = computed("indeterminate");
  const disabled = prop("disabled");
  const readOnly = prop("readOnly");
  const invalid = prop("invalid");
  // The source is read once, when focus lands, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = state.matches("focused") ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const stateAttrs = {
    "data-state": computed("state"),
    "data-disabled": dataAttr(disabled),
    "data-readonly": dataAttr(readOnly),
    "data-invalid": dataAttr(invalid),
    "data-focus-visible": dataAttr(focusVisible),
    "data-focus-source": focusSource ?? undefined,
  };

  return {
    checked,
    indeterminate,
    disabled,
    focusSource,
    focusVisible,

    setChecked(next): void {
      send({ type: "CHECKED.SET", checked: next });
    },
    toggle(): void {
      send({ type: "CHECKED.TOGGLE" });
    },

    getRootProps: (): T["label"] =>
      normalize.label({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir: prop("dir"),
        // Without this a double click on the row selects the label text instead of
        // reading as two toggles.
        style: { userSelect: "none" },
      }),

    getLabelProps: (): T["element"] =>
      normalize.element({ ...parts.label.attrs, ...stateAttrs, id: getLabelId(scope) }),

    getControlProps: (): T["element"] =>
      normalize.element({
        ...parts.control.attrs,
        ...stateAttrs,
        // The input carries the semantics; this is the box that gets drawn.
        "aria-hidden": ariaAttr(true),
      }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({ ...parts.indicator.attrs, ...stateAttrs, "aria-hidden": ariaAttr(true) }),

    getHiddenInputProps: (): T["input"] =>
      normalize.input({
        ...parts.hiddenInput.attrs,
        id: getHiddenInputId(scope),
        type: "checkbox",
        // Visually hidden rather than `display: none`: it stays focusable, stays
        // in the tab order and stays the thing a screen reader reads.
        style: visuallyHiddenStyle,
        checked: checked === true,
        disabled,
        required: prop("required"),
        name: prop("name"),
        value: prop("value"),
        form: prop("form"),
        "aria-invalid": ariaAttr(invalid),
        "aria-describedby": prop("describedBy"),
        // `readOnly` does nothing on a checkbox in HTML — the browser ignores it
        // and toggles anyway — so the guard lives in the machine and the promise
        // to assistive technology is made here.
        "aria-readonly": ariaAttr(readOnly),
        onChange(event) {
          if (event.defaultPrevented) return;
          send({ type: "CHECKED.TOGGLE" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.BLUR" });
        },
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "checkbox";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getLabelId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "label");
}

export function getHiddenInputId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "hiddenInput");
}

export function getHiddenInputEl(scope: Scope): HTMLInputElement | null {
  return scope.getById<HTMLInputElement>(getHiddenInputId(scope));
}

/**
 * A real `<input type="checkbox">` does the work, visually hidden inside the
 * label that is the root. That is not a fallback, it is the design: form
 * association, the click a `<label>` forwards, Space, autofill, and the
 * "required" validation message all come free and correct, and none of them can
 * be re-implemented as well as the browser already does them.
 *
 * Which leaves exactly one thing the platform cannot express through markup:
 * `indeterminate` is a DOM property, not an attribute. It is written in an action
 * on every change, because an attribute-only adapter — SSR, or a framework that
 * only diffs attributes — would otherwise never set it at all.
 */

import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getHiddenInputEl } from "./checkbox.dom";
import type { CheckboxSchema, CheckedState } from "./checkbox.types";

export const machine: Machine<CheckboxSchema> = createMachine<CheckboxSchema>({
  props({ props }) {
    return {
      disabled: false,
      invalid: false,
      required: false,
      readOnly: false,
      value: "on",
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      checked: bindable<CheckedState>(() => ({
        defaultValue: prop("defaultChecked") ?? false,
        value: prop("checked"),
        onChange: (checked) => prop("onCheckedChange")?.({ checked }),
        debugLabel: "checkbox checked",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    indeterminate: ({ context }) => context.get("checked") === "indeterminate",
    state({ context }) {
      const checked = context.get("checked");
      if (checked === "indeterminate") return "indeterminate";
      return checked ? "checked" : "unchecked";
    },
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality"],

  watch({ context, track, action }) {
    track(
      () => [context.get("checked")],
      () => action(["syncIndeterminate"]),
    );
  },

  entry: ["syncIndeterminate"],

  on: {
    "CHECKED.TOGGLE": { guard: "isInteractive", actions: ["toggleChecked"] },
    "CHECKED.SET": { guard: "isInteractive", actions: ["setChecked"] },
    "ROOT.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource"],
      on: { "ROOT.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      // Read-only is not disabled: the control stays focusable and announced, it
      // simply refuses to change — which is what a form in review mode wants.
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    },

    actions: {
      // From indeterminate a click goes to checked, never back to unchecked: the
      // mixed state is the parent's summary, and the user asking for a change is
      // asking for "all of them" (APG, tri-state checkbox).
      toggleChecked({ context }) {
        context.set("checked", (checked) => checked !== true);
      },
      setChecked({ context, event }) {
        if (event.type === "CHECKED.SET") context.set("checked", event.checked);
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
      syncIndeterminate({ scope, computed }) {
        const input = getHiddenInputEl(scope);
        if (input === null) return;
        input.indeterminate = computed("indeterminate");
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

/** Tri-state, and `"indeterminate"` is a state the user cannot reach by clicking. */
export type CheckedState = boolean | "indeterminate";

export interface CheckboxCheckedChangeDetails {
  readonly checked: CheckedState;
}

export interface CheckboxMachineProps {
  readonly dir?: Direction | undefined;
  readonly checked?: CheckedState | undefined;
  readonly defaultChecked?: CheckedState | undefined;
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly required?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  /** Form association, straight through to the hidden native input. */
  readonly name?: string | undefined;
  readonly value?: string | undefined;
  readonly form?: string | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  readonly onCheckedChange?: ((details: CheckboxCheckedChangeDetails) => void) | undefined;
}

export interface ResolvedCheckboxMachineProps extends CheckboxMachineProps {
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly required: boolean;
  readonly readOnly: boolean;
  readonly value: string;
}

export interface CheckboxSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedCheckboxMachineProps;
  context: { checked: CheckedState; focusSource: InputModality | null };
  computed: { indeterminate: boolean; state: "checked" | "unchecked" | "indeterminate" };
  event:
    | { type: "CHECKED.TOGGLE" }
    | { type: "CHECKED.SET"; checked: CheckedState }
    | { type: "ROOT.FOCUS" }
    | { type: "ROOT.BLUR" };
  action:
    | "toggleChecked"
    | "setChecked"
    | "captureFocusSource"
    | "clearFocusSource"
    | "syncIndeterminate";
  guard: "isInteractive";
  effect: "trackModality";
}

export interface CheckboxApi<T extends PropTypes = PropTypes> {
  readonly checked: CheckedState;
  readonly indeterminate: boolean;
  readonly disabled: boolean;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  setChecked(checked: CheckedState): void;
  toggle(): void;
  getRootProps(): T["label"];
  getLabelProps(): T["element"];
  getControlProps(): T["element"];
  getIndicatorProps(): T["element"];
  getHiddenInputProps(): T["input"];
}

export { anatomy, type CheckboxPart, parts } from "./checkbox.anatomy";
export { connect } from "./checkbox.connect";
export { getHiddenInputEl, getHiddenInputId, getLabelId, getRootId } from "./checkbox.dom";
export { machine } from "./checkbox.machine";
export type {
  CheckboxApi,
  CheckboxCheckedChangeDetails,
  CheckboxMachineProps,
  CheckboxSchema,
  CheckedState,
  ResolvedCheckboxMachineProps,
} from "./checkbox.types";

/**
 * The context a checkbox reads to find the group it sits in — deliberately *not*
 * inside the group component's folder, for the reason `field-context` spells out:
 * a checkbox that imported `components/checkbox-group/checkbox-group` to reach it
 * would drag the group's machine and DOM helpers into every bundle that has a
 * checkbox in it.
 *
 * **The role rule.** In a group, a checkbox with a `value` is an item; the one
 * without is the tri-state summary. That is not a flag invented here — an item is
 * defined by the value it submits, so a box with nothing to submit cannot be one,
 * and the only other thing it can be is the summary. It is also exactly how the
 * group finds its items in the DOM: they are the boxes carrying its name, and the
 * summary carries none.
 */

import type { CheckboxCheckedChangeDetails, CheckedState } from "@standarui/core/checkbox";
import { createPartContext, type PartContext } from "./part-context";

/**
 * What a checkbox needs from its group, plus the getter the group's own label
 * reads. Stated structurally rather than imported: `CheckboxGroupApi` lives in the
 * component, and importing it here would put the dependency back the way it came.
 *
 * The getter is `object` because that is all `useRender` asks of it; the group's
 * real api, which returns React's own prop types, satisfies it.
 */
export interface CheckboxGroupContextValue {
  /** Every item carries it, and it is what makes them items. */
  readonly name: string;
  readonly disabled: boolean;
  readonly readOnly: boolean;
  readonly invalid: boolean;
  readonly form: string | undefined;
  readonly parentChecked: CheckedState;
  readonly parentDisabled: boolean;
  isChecked(value: string): boolean;
  toggleValue(value: string): void;
  toggleAll(checked: boolean): void;
  getLabelProps(): object;
}

export const CheckboxGroupContext: PartContext<CheckboxGroupContextValue> =
  createPartContext("CheckboxGroup");

/** `null` outside a group, which is what lets a checkbox work on its own. */
export function useCheckboxGroupContext(): CheckboxGroupContextValue | null {
  return CheckboxGroupContext.useOptional();
}

export interface CheckboxGroupInheritable {
  readonly value?: string | undefined;
  readonly checked?: CheckedState | undefined;
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  readonly onCheckedChange?: ((details: CheckboxCheckedChangeDetails) => void) | undefined;
}

/**
 * What a checkbox inherits from its group, handed to the machine as props rather
 * than merged over its output — the same reason a field's are.
 *
 * `??` everywhere except the name: a box that says `disabled={false}` inside a
 * disabled group means it, but a box that renames itself leaves the field the
 * group is submitting, and stops being one of its items at all.
 */
export function inheritFromCheckboxGroup<T extends CheckboxGroupInheritable>(
  props: T,
  group: CheckboxGroupContextValue | null,
): T {
  if (group === null) return props;

  const shared = {
    readOnly: props.readOnly ?? group.readOnly,
    invalid: props.invalid ?? group.invalid,
  };

  if (props.value === undefined) {
    return {
      ...props,
      ...shared,
      // No name, so it submits nothing and the group does not count it as an item.
      name: undefined,
      checked: props.checked ?? group.parentChecked,
      disabled: props.disabled ?? group.parentDisabled,
      onCheckedChange(details: CheckboxCheckedChangeDetails): void {
        // From "mixed" a press goes to checked, which is what the checkbox
        // machine already does and what APG asks a tri-state parent to do.
        group.toggleAll(details.checked === true);
        props.onCheckedChange?.(details);
      },
    };
  }

  const value = props.value;
  return {
    ...props,
    ...shared,
    name: group.name,
    form: props.form ?? group.form,
    checked: props.checked ?? group.isChecked(value),
    disabled: props.disabled ?? group.disabled,
    onCheckedChange(details: CheckboxCheckedChangeDetails): void {
      group.toggleValue(value);
      props.onCheckedChange?.(details);
    },
  };
}

import * as checkbox from "@standarui/core/checkbox";
import type { ReactNode } from "react";
import { inheritFromCheckboxGroup, useCheckboxGroupContext } from "../../checkbox-group-context";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type CheckboxApi = checkbox.CheckboxApi<ReactPropTypes>;

const CheckboxContext = createPartContext<CheckboxApi>("Checkbox");

export interface UseCheckboxProps extends checkbox.CheckboxMachineProps, MachineRuntimeProps {}

export function useCheckbox(props: UseCheckboxProps): CheckboxApi {
  return checkbox.connect(useMachine(checkbox.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "checked",
  "defaultChecked",
  "disabled",
  "invalid",
  "required",
  "readOnly",
  "name",
  "value",
  "form",
  "describedBy",
  "onCheckedChange",
] as const;

export interface CheckboxRootProps extends UseCheckboxProps, PartProps<"label", UseCheckboxProps> {}

export function CheckboxRoot(props: CheckboxRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const group = useCheckboxGroupContext();
  // In a group, the group is the only context: it has already inherited from the
  // field on its own root, and handing every box the field's control id would put
  // the same id on all of them.
  const api = useCheckbox(
    group === null
      ? {
          ...inheritFromField(machineProps, field),
          ids: { hiddenInput: field?.controlProps.id, ...machineProps.ids },
        }
      : inheritFromCheckboxGroup(machineProps, group),
  );

  return (
    <CheckboxContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "label",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </CheckboxContext.Provider>
  );
}

export const CheckboxLabel: (props: PartProps<"span">) => ReactNode = createPart(CheckboxContext, {
  name: "CheckboxLabel",
  element: "span",
  props: (api) => api.getLabelProps(),
});

export const CheckboxControl: (props: PartProps<"span">) => ReactNode = createPart(
  CheckboxContext,
  {
    name: "CheckboxControl",
    element: "span",
    props: (api) => api.getControlProps(),
  },
);

export const CheckboxIndicator: (props: PartProps<"span">) => ReactNode = createPart(
  CheckboxContext,
  { name: "CheckboxIndicator", element: "span", props: (api) => api.getIndicatorProps() },
);

export const CheckboxHiddenInput: (props: PartProps<"input">) => ReactNode = createPart(
  CheckboxContext,
  { name: "CheckboxHiddenInput", element: "input", props: (api) => api.getHiddenInputProps() },
);

/**
 * `<Checkbox label="…"/>` — the bare name beside the parts: one root, four
 * children, no collection. The root is the `<label>` itself
 * (`checkbox.anatomy.ts` has no separate element for it), so the composed
 * props are the root's own — `render`, `asChild`, every machine prop — and
 * `children` is excluded from them: what the root contains is the four parts
 * below, hardcoded here, not a slot a consumer fills.
 *
 * `checked` stays exactly `CheckedState` (`boolean | "indeterminate"`,
 * `checkbox.types.ts`) because it is `CheckboxMachineProps`'s own field,
 * reached here through `UseCheckboxProps` — the composed layer invents no
 * third state and no narrower type for it.
 *
 * One translation the type system cannot make on its own: `label` names the
 * box, but `CheckboxLabel` is placed only once it is given. Leaving it out is
 * not a defect to guard against — a checkbox living under a `Field` is named
 * by the field's own label instead, through the native `label[for]` the root
 * already wires to the hidden input (`checkbox.tsx`, `ids.hiddenInput`) — so
 * an empty part written unconditionally would double that name rather than
 * complete it.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  CheckboxControl,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxRoot,
  type UseCheckboxProps,
} from "./checkbox";

export interface CheckboxComposedProps
  extends UseCheckboxProps,
    Omit<PartProps<"label", UseCheckboxProps>, "children"> {
  /** The visible text. Omit it only where something else names the box — see above. */
  readonly label?: ReactNode;
}

export function Checkbox(props: CheckboxComposedProps): ReactNode {
  const { label, ...root } = props;

  return (
    <CheckboxRoot {...root}>
      <CheckboxHiddenInput />
      <CheckboxControl>
        <CheckboxIndicator />
      </CheckboxControl>
      {label == null ? null : <CheckboxLabel>{label}</CheckboxLabel>}
    </CheckboxRoot>
  );
}

export type {
  CheckboxCheckedChangeDetails,
  CheckboxMachineProps,
  CheckedState,
} from "@standarui/core/checkbox";
export {
  type CheckboxApi,
  CheckboxControl,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxRoot,
  type CheckboxRootProps,
  type UseCheckboxProps,
  useCheckbox,
} from "./checkbox";
export { Checkbox, type CheckboxComposedProps } from "./composed";
